import{_ as d,C as r,o,c as n,E as a,a4 as i}from"./chunks/framework.BMj-uaUw.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"前面十个单元攒下的东西，这一节开始用","slug":"前面十个单元攒下的东西-这一节开始用","link":"#前面十个单元攒下的东西-这一节开始用","children":[]},{"level":2,"title":"综合项目是什么","slug":"综合项目是什么","link":"#综合项目是什么","children":[]},{"level":2,"title":"本单元的知识地图","slug":"本单元的知识地图","link":"#本单元的知识地图","children":[]},{"level":2,"title":"这次课的 4 学时怎么用","slug":"这次课的-4-学时怎么用","link":"#这次课的-4-学时怎么用","children":[]},{"level":2,"title":"这个单元的产出","slug":"这个单元的产出","link":"#这个单元的产出","children":[]},{"level":2,"title":"开始之前","slug":"开始之前","link":"#开始之前","children":[]},{"level":2,"title":"读完之后","slug":"读完之后","link":"#读完之后","children":[]}],"relativePath":"unit11/index.md","filePath":"unit11/index.md","lastUpdated":1789500889000}'),s={name:"unit11/index.md"};function l(c,t,h,p,g,u){const e=r("UnitMeta");return o(),n("div",null,[a(e,{unit:"单元 11",title:"项目启动与核心业务实现",module:"模块五 · 综合项目实战",hours:"4 学时",week:"第 11 周",goals:["能把一段业务描述拆成页面清单、路由表和接口清单三份文档","能独立初始化一个带路由、状态管理、请求层与 UI 库的工程骨架","能搭出侧边栏 + 顶栏 + 内容区的后台布局，并让面包屑跟着路由自动变","能按统一模板写出列表页与表单页，包含查询、分页、四态、校验与提交"],outcomes:["项目页面清单与接口清单","可运行的工程骨架","活动管理模块的列表页与表单页"]}),t[0]||(t[0]=i('<h2 id="前面十个单元攒下的东西-这一节开始用" tabindex="-1">前面十个单元攒下的东西，这一节开始用 <a class="header-anchor" href="#前面十个单元攒下的东西-这一节开始用" aria-label="Permalink to &quot;前面十个单元攒下的东西，这一节开始用&quot;">​</a></h2><p>到这里，你已经会写组件、会配路由、会管状态、会封请求层。但这些能力是分开练的 —— 每个单元一个小练习，做完就丢。</p><p>真实项目不是这样。真实项目是给你一段业务描述，让你自己判断：<strong>要做几个页面？每个页面归哪个路由？数据从哪个接口来？哪些状态要放到全局？</strong></p><p>这个判断过程没法靠背 API 学会，只能做一遍。</p><p>所以单元 11 和单元 12 不再讲新语法。这两次课的任务是：<strong>把前面十次课的工具，全部装到一个真实项目上，把它做出来。</strong></p><div class="tip custom-block"><p class="custom-block-title">这两次课的节奏</p><p>单元 11（第 11 周）：<strong>从需求到页面，把骨架搭起来，做出第一个完整业务模块。</strong> 单元 12（第 12 周）：<strong>联调、优化、部署、答辩，把它交出去。</strong></p></div><h2 id="综合项目是什么" tabindex="-1">综合项目是什么 <a class="header-anchor" href="#综合项目是什么" aria-label="Permalink to &quot;综合项目是什么&quot;">​</a></h2><p><strong>校园活动服务平台 · 管理端</strong> —— 给学生会和社团用的活动管理后台。</p><p>一条主线贯穿全部功能：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>活动发布  →  报名审核  →  场次安排</span></span></code></pre></div><p>两个角色：</p><table tabindex="0"><thead><tr><th>角色</th><th>能做什么</th></tr></thead><tbody><tr><td>活动组织者</td><td>创建活动、提交发布、查看自己活动下的报名、给报名记录审核、安排场次与场地</td></tr><tr><td>审核员</td><td>查看全部活动、审核报名（通过 / 驳回）、维护场地信息</td></tr></tbody></table><p>五个功能模块：</p><table tabindex="0"><thead><tr><th>模块</th><th>对应路由</th><th>本单元 / 单元 12</th></tr></thead><tbody><tr><td>登录鉴权</td><td><code>/login</code></td><td>单元 12 联调时串起来（单元 9 已练过）</td></tr><tr><td>活动管理</td><td><code>/activity</code></td><td><strong>本单元重点</strong>：列表页 + 表单页</td></tr><tr><td>报名审核</td><td><code>/signup</code></td><td>单元 12 参考实现</td></tr><tr><td>场次与场地</td><td><code>/session</code>、<code>/venue</code></td><td>单元 12 参考实现</td></tr><tr><td>数据看板</td><td><code>/dashboard</code></td><td>单元 12 参考实现</td></tr></tbody></table><p>完整的业务规则见<a href="/frontend-engineering-course/project/rules.html">综合项目 · 业务规则与状态流转</a>。<strong>这个单元动笔之前先把它读一遍</strong>，不然后面写代码时会反复推翻自己。</p><div class="tip custom-block"><p class="custom-block-title">项目还有第二个端</p><p>学生用的手机端（uni-app 写的用户端）不在这个单元的范围内 —— 它不占课时， 是管理端跑通之后的延伸内容。想做的同学做完单元 12 再进<a href="/frontend-engineering-course/mobile/">用户端专栏</a>， 从“为什么是 uni-app”顺序读。两端的页面清单和接口约定都在项目文档里，见<a href="/frontend-engineering-course/project/mobile.html">用户端需求规格</a>。</p></div><h2 id="本单元的知识地图" tabindex="-1">本单元的知识地图 <a class="header-anchor" href="#本单元的知识地图" aria-label="Permalink to &quot;本单元的知识地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>小节</th><th>讲什么</th><th>解决什么问题</th></tr></thead><tbody><tr><td><a href="/frontend-engineering-course/unit11/01-requirements.html">11.1 从需求到页面清单</a></td><td>把一段业务描述拆成页面清单、路由表、接口清单</td><td>不知道从哪下手，就先把“要做什么”写清楚</td></tr><tr><td><a href="/frontend-engineering-course/unit11/02-scaffold.html">11.2 工程初始化与目录规划</a></td><td>建工程、装依赖、定目录、配别名与环境变量</td><td>骨架不规整，写到第三个模块就乱了</td></tr><tr><td><a href="/frontend-engineering-course/unit11/03-layout.html">11.3 布局骨架与嵌套路由</a></td><td>侧边栏 + 顶栏 + 内容区、菜单跟着路由高亮、面包屑自动生成</td><td>页面之间没有统一的壳，每页都要重复写一遍头部</td></tr><tr><td><a href="/frontend-engineering-course/unit11/04-list-page.html">11.4 列表页标准做法</a></td><td>查询条件 → 表格 → 分页 → 四态 → 行操作</td><td>列表页占后台工作量的一半以上，必须形成模板</td></tr><tr><td><a href="/frontend-engineering-course/unit11/05-form-page.html">11.5 表单页标准做法</a></td><td>新增与编辑共用一个组件、校验、提交、离开提醒</td><td>表单是 bug 最集中的地方，要有固定套路</td></tr><tr><td><a href="/frontend-engineering-course/unit11/ai-collaboration.html">AI 协作 · 规格驱动开发的流程</a></td><td>先写规格再让它实现、一次不让它生成太多、按 AGENTS.md 验收</td><td>一次说清比反复返工划算</td></tr></tbody></table><p>四节是递进关系：<strong>先想清楚要做什么</strong>（11.1），<strong>再把壳搭起来</strong>（11.2、11.3），<strong>然后按模板填肉</strong>（11.4、11.5）。</p><h2 id="这次课的-4-学时怎么用" tabindex="-1">这次课的 4 学时怎么用 <a class="header-anchor" href="#这次课的-4-学时怎么用" aria-label="Permalink to &quot;这次课的 4 学时怎么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>时长</th><th>做什么</th></tr></thead><tbody><tr><td>讲评 + 拆解</td><td>0.8 学时</td><td>讲 11.1：现场把“活动管理”这一段需求拆成三份清单，学生跟着拆自己的模块</td></tr><tr><td>骨架搭建</td><td>1.2 学时</td><td>按 11.2、11.3 建工程、配目录、搭布局，跑起来看到空壳</td></tr><tr><td>列表页实操</td><td>1.2 学时</td><td>按 11.4 的模板做出活动列表页，接上 mock 数据</td></tr><tr><td>表单页实操 + 复盘</td><td>0.8 学时</td><td>按 11.5 做新增 / 编辑表单；展示两三个同学的实现，对比页面清单拆得准不准</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">这次课最容易跑偏的地方</p><p>最常见的两种情况：</p><p><strong>一、先写代码，后想需求。</strong> 打开编辑器就建组件，写到一半发现“报名审核”这个页面到底该放在活动详情里，还是单独一个菜单项？推翻重来。<strong>11.1 花的那 40 分钟，能省掉后面两个小时。</strong></p><p><strong>二、把前十个单元学到的东西一次性全堆上去。</strong> 一个新增活动的表单，塞了自定义指令、provide/inject、递归组件、画板……能用的地方全用一遍。<strong>不要这样。</strong> 用什么取决于问题需要什么，不取决于你刚学会什么。</p></div><h2 id="这个单元的产出" tabindex="-1">这个单元的产出 <a class="header-anchor" href="#这个单元的产出" aria-label="Permalink to &quot;这个单元的产出&quot;">​</a></h2><p>这次课要交三样东西，都能直接进最后的项目仓库：</p><p><strong>一、项目页面清单与接口清单</strong></p><p>一张表，覆盖你负责的模块。每行是“页面 → 路由 → 主要接口 → 涉及角色”：</p><table tabindex="0"><thead><tr><th>页面</th><th>路由</th><th>主要接口</th><th>可访问角色</th></tr></thead><tbody><tr><td>活动列表</td><td><code>/activity</code></td><td><code>GET /api/activities</code></td><td>组织者、审核员</td></tr><tr><td>活动详情</td><td><code>/activity/:id</code></td><td><code>GET /api/activities/:id</code></td><td>组织者、审核员</td></tr><tr><td>新增活动</td><td><code>/activity/create</code></td><td><code>POST /api/activities</code></td><td>组织者</td></tr><tr><td>编辑活动</td><td><code>/activity/:id/edit</code></td><td><code>PUT /api/activities/:id</code></td><td>组织者</td></tr></tbody></table><p>这份表不是交差用的，它是你下一步写路由表的直接依据。<strong>页面清单写不准，路由表一定写乱。</strong></p><p><strong>二、可运行的工程骨架</strong></p><p>判定标准只有一条：<code>npm run dev</code> 起来之后，左侧菜单能点，点了内容区会切换，刷新页面停在原地（不是跳回首页）。内容区是空白的 <code>&lt;RouterView /&gt;</code> 也没关系。</p><p><strong>三、活动管理模块的列表页与表单页</strong></p><p>要求：</p><table tabindex="0"><thead><tr><th>要求</th><th>说明</th></tr></thead><tbody><tr><td>列表有查询</td><td>至少两个查询条件（关键字、状态），点“查询”生效</td></tr><tr><td>列表有分页</td><td>页码、每页条数都要能用</td></tr><tr><td>四态齐全</td><td>加载中、成功有数据、成功无数据、请求失败，四种都要能看到</td></tr><tr><td>表单能校验</td><td>必填、长度、名额为正整数、截止时间必须晚于当前时间</td></tr><tr><td>新增与编辑共用</td><td>同一个表单组件，靠路由参数区分</td></tr><tr><td>提交后回到列表</td><td>并提示结果，列表刷新</td></tr></tbody></table><details class="details custom-block"><summary>页面清单写得好不好，看这三个标准</summary><p><strong>一、每个页面有且只有一个主要职责。</strong> “活动详情”和“编辑活动”是两个页面，因为一个是读、一个是写。合并成一个页面会导致权限判断和状态清理都变复杂。</p><p><strong>二、路由能体现出层级。</strong> <code>/activity/:id/signups</code> 比 <code>/signup-list?activityId=3</code> 好，因为前者一眼能看出报名是挂在活动下的，面包屑也能自动生成。</p><p><strong>三、清单能反推出接口。</strong> 页面清单写完，接口清单应该基本同时写完。如果需要另外想一遍，说明你的页面拆得和数据结构对不上。</p><p>反过来说，最常见的错误是把“活动列表”拆成“我发布的活动”“全部活动”“已下架活动”三个页面。这三个页面结构完全一样，只有筛选条件不同 —— 应该是一个页面，靠查询参数区分。</p></details><h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2><p>这个单元有前置条件，缺一个都会卡住：</p><ul><li><strong>前十个单元的代码你是自己写的。</strong> 如果你单元 9 的路由是抄的，这里会卡在“为什么菜单点不动”。卡住了就回去补，不要硬撑。</li><li><strong>项目已经建好 Git 仓库并且完成了第一次提交。</strong> 单元 11 的改动量很大，没有版本控制，改崩了只能重来。</li><li><strong>已经读完<a href="/frontend-engineering-course/project/rules.html">业务规则</a>和<a href="/frontend-engineering-course/project/api.html">接口约定</a>。</strong> 这两个页面是本单元所有代码的依据。</li></ul><h2 id="读完之后" tabindex="-1">读完之后 <a class="header-anchor" href="#读完之后" aria-label="Permalink to &quot;读完之后&quot;">​</a></h2><p>单元 11 结束时，你手上是一个能跑、能查、能填的活动管理模块。剩下四个模块的结构与它高度相似 —— 单元 12 的<a href="/frontend-engineering-course/project/impl-activity.html">参考实现</a>给出逐模块的写法，你可以照着把其余模块补齐，也可以自己先做一遍再对照。</p><p>下一步：<a href="/frontend-engineering-course/unit11/01-requirements.html">11.1 从需求到页面清单</a>。</p>',40))])}const f=d(s,[["render",l]]);export{m as __pageData,f as default};
